window.HOEREN_TESTS[99] = {"id":"abschlussfeier-und-zukunftsplaene","name":"Abschlussfeier und Zukunftspläne","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Schüler: Die Abschlussfeier findet bald statt. Aber nicht am Freitag, sondern am Samstagabend um 18 Uhr in der Aula. Es gibt eine Rede der Direktorin, dann die Zeugnisse und danach ein Buffet. Eltern und Geschwister sind herzlich eingeladen. Bitte zieht euch festlich an. Wir freuen uns!","gender":"f","q":"Wann ist die Abschlussfeier?","opts":["Am Freitag.","Am Samstagabend.","Am Sonntag."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Ich habe meine Prüfung bestanden! Ich bin so glücklich und erleichtert. Jetzt fange ich im Herbst mit der Ausbildung an. Wir müssen das feiern! Komm doch am Wochenende vorbei, ich lade alle ein. Bring auch deine Freundin mit. Ruf zurück, bis bald!","gender":"m","q":"Was hat Markus geschafft?","opts":["Er hat seine Prüfung bestanden.","Er hat einen Job gefunden.","Er ist umgezogen."],"correct":0},{"transcript":"Achtung Absolventen: Für das Klassenfoto treffen wir uns vor der Feier, schon um 17 Uhr, vor dem Schuleingang. Bitte seid pünktlich, sonst fehlt ihr auf dem Bild. Jeder bekommt später einen Abzug. Bringt gute Laune mit, es soll ein schönes Erinnerungsfoto werden. Bis später, wir freuen uns!","gender":"m","q":"Wann ist das Klassenfoto?","opts":["Um 18 Uhr.","Um 17 Uhr.","Nach der Feier."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hey, nach meinem Abschluss will ich erst mal ein Jahr ins Ausland, bevor ich studiere. Ich möchte reisen und meine Sprachkenntnisse verbessern. Meine Eltern sind einverstanden. Du hast doch auch bald deinen Abschluss. Was sind deine Pläne? Lass uns reden, ruf zurück!","gender":"f","q":"Was will Anna nach dem Abschluss machen?","opts":["Sofort studieren.","Sofort arbeiten.","Ein Jahr ins Ausland."],"correct":2},{"transcript":"Liebe Eltern: Wir bitten um Ihre Hilfe für das Buffet bei der Abschlussfeier. Wenn jeder einen Salat oder einen Kuchen mitbringt, haben wir genug für alle. Bitte tragen Sie sich in die Liste ein, damit wir nicht zehnmal denselben Salat haben. Getränke besorgt die Schule. Vielen Dank!","gender":"f","q":"Worum bittet die Schule die Eltern?","opts":["Um Geld.","Um Getränke.","Um Essen für das Buffet."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer plant was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Schule ist bald vorbei. Weißt du schon was du danach machst?"},{"speaker":"Lisa","gender":"f","text":"Ich weiß es seit einem Monat. Sag mir zuerst deinen Plan."},{"speaker":"Lukas","gender":"m","text":"Ich wähle ein Studium in Berlin. Ich will dort lange lernen und bleiben."},{"speaker":"Lisa","gender":"f","text":"Das passt zu dir. Will jemand nur reisen und nichts Festes machen?"},{"speaker":"Lukas","gender":"m","text":"Nur reisen will dieses Jahr keiner. Alle haben einen festen Plan."},{"speaker":"Lisa","gender":"f","text":"Ich wähle eine Ausbildung im Laden, weil ich gern mit Menschen arbeite."},{"speaker":"Lukas","gender":"m","text":"Du magst Menschen. Was hat Tom vor?"},{"speaker":"Lisa","gender":"f","text":"Tom will ins Ausland gehen. Er möchte ein Jahr in Kanada leben."},{"speaker":"Lukas","gender":"m","text":"Kanada ist weit weg. Macht jemand ein Praktikum in einer Firma?"},{"speaker":"Lisa","gender":"f","text":"Ein Praktikum macht auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara braucht schnell Geld für ein Auto."},{"speaker":"Lisa","gender":"f","text":"Sara will sofort arbeiten. Sie sucht eine Arbeit im Büro."},{"speaker":"Lukas","gender":"m","text":"Das verstehe ich. Tim sucht noch eine Aufgabe mit Menschen."},{"speaker":"Lisa","gender":"f","text":"Tim macht ein soziales Jahr. Er hilft im Krankenhaus und wohnt neben dem Haus."},{"speaker":"Lukas","gender":"m","text":"Das ist eine starke Idee."},{"speaker":"Lisa","gender":"f","text":"Erst feiern wir zusammen und dann geht es los."}],"options":[{"letter":"a","text":"Ins Ausland gehen"},{"letter":"b","text":"Soziales Jahr"},{"letter":"c","text":"Noch nicht entschieden"},{"letter":"d","text":"Eine Firma gründen"},{"letter":"e","text":"Praktikum"},{"letter":"f","text":"Sofort arbeiten"},{"letter":"g","text":"Ausbildung"},{"letter":"h","text":"Reisen"},{"letter":"i","text":"Studium"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"g"},{"person":"Tom","correct":"a"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Schülerin","gender":"f","text":"Hast du deine Note schon? Eine Eins, eine Zwei oder eine Drei?"},{"speaker":"Schüler","gender":"m","text":"Ja, eine Zwei. Eine Drei hätte mich geärgert, eine Eins war knapp."},{"speaker":"Schülerin","gender":"f","text":"Eine Eins, ich kann es kaum glauben! Nicht die Zwei und nicht die Drei."},{"speaker":"Schüler","gender":"m","text":"Wow, gratuliere! Du hast eine Eins, ich eine Zwei, eine Drei hat niemand von uns."},{"speaker":"Schülerin","gender":"f","text":"Danke, ich bin so froh über die Eins."}],"q":"Welche Note hat die Schülerin?","opts":["Eine Zwei.","Eine Eins.","Eine Drei."],"correct":1},{"lines":[{"speaker":"Mutter","gender":"f","text":"Was ziehst du zur Feier an? Das schwarze Kleid, das blaue oder eine Hose?"},{"speaker":"Tochter","gender":"f","text":"Das blaue Kleid. Die Hose ist zu sportlich, das schwarze zu ernst."},{"speaker":"Mutter","gender":"f","text":"Nicht das schwarze? Und keine Hose?"},{"speaker":"Tochter","gender":"f","text":"Nein, das blaue ist festlicher. Nicht das schwarze und keine Hose, das blaue Kleid."},{"speaker":"Mutter","gender":"f","text":"Gut, dann das blaue Kleid. Die Schuhe hole ich dir."}],"q":"Was zieht die Tochter an?","opts":["Das schwarze Kleid.","Eine Hose.","Das blaue Kleid."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Was möchtest du als Geschenk? Ein Auto, eine Reise oder Geld?"},{"speaker":"Sohn","gender":"m","text":"Eigentlich nichts Großes. Ein Auto ist zu viel, Geld allein ist langweilig."},{"speaker":"Vater","gender":"m","text":"Komm schon, du hast es verdient. Auto, Reise oder Geld?"},{"speaker":"Sohn","gender":"m","text":"Na gut, vielleicht eine Reise. Kein Auto und nicht nur Geld, eine Reise wäre schön."},{"speaker":"Vater","gender":"m","text":"Eine Reise also. Das machen wir, versprochen."}],"q":"Was wünscht sich der Sohn?","opts":["Ein Auto.","Eine Reise.","Geld."],"correct":1},{"lines":[{"speaker":"Lehrerin","gender":"f","text":"Was sind deine Pläne, Tom? Koch, Mechaniker oder Verkäufer?"},{"speaker":"Tom","gender":"m","text":"Ich beginne eine Ausbildung. Nicht als Mechaniker und nicht als Verkäufer."},{"speaker":"Lehrerin","gender":"f","text":"In welchem Beruf? Als Koch, oder doch Mechaniker?"},{"speaker":"Tom","gender":"m","text":"Als Koch, ich liebe das Kochen. Nicht als Mechaniker und nicht als Verkäufer, als Koch."},{"speaker":"Lehrerin","gender":"f","text":"Das passt zu dir. Viel Erfolg als Koch!"}],"q":"Welche Ausbildung macht Tom?","opts":["Als Koch.","Als Mechaniker.","Als Verkäufer."],"correct":0},{"lines":[{"speaker":"Freundin","gender":"f","text":"Bleiben wir in Kontakt? Oder uns nie wiedersehen, oder zusammen studieren?"},{"speaker":"Freund","gender":"m","text":"Klar, auf jeden Fall in Kontakt bleiben. Nie wiedersehen will ich nicht, zusammen studieren wir nicht."},{"speaker":"Freundin","gender":"f","text":"Machen wir ein Klassentreffen? Also Kontakt, und nicht für immer Schluss?"},{"speaker":"Freund","gender":"m","text":"Ja, jedes Jahr, das wäre schön. In Kontakt bleiben, uns nicht aus den Augen verlieren, und nicht unbedingt zusammen studieren."},{"speaker":"Freundin","gender":"f","text":"Abgemacht, jedes Jahr. Ich freue mich."}],"q":"Was wollen die beiden machen?","opts":["In Kontakt bleiben.","Sich nie wiedersehen.","Zusammen studieren."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Direktorin Wagner über die Abschlussfeier und die Zukunft der Schüler. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Wagner, was bedeutet dieser Tag für die Schüler?"},{"speaker":"Wagner","gender":"f","text":"Es ist ein großer Tag. Sie haben viele Jahre gelernt. Jetzt beginnt etwas Neues. Für mich ist dieser Tag ein großer Tag, das spürt man in der Aula."},{"speaker":"Reporter","gender":"m","text":"Sind die jungen Leute unsicher wegen der Zukunft? Müssen sie heute schon alles wissen?"},{"speaker":"Wagner","gender":"f","text":"Manche schon. Ich sage ihnen: Ihr müsst nicht heute schon alles wissen. Die Schüler müssen heute noch nicht alles wissen, das betone ich oft."},{"speaker":"Reporter","gender":"m","text":"Müssen alle studieren, oder ist eine Ausbildung genauso gut?"},{"speaker":"Wagner","gender":"f","text":"Nein, eine Ausbildung ist genauso gut wie ein Studium. Wir brauchen auch Handwerker und Pfleger. Beides ist wertvoll, das Studium und die Ausbildung."},{"speaker":"Reporter","gender":"m","text":"Was geben Sie den Schülern mit? Sollen sie nach der Schule nicht mehr lernen?"},{"speaker":"Wagner","gender":"f","text":"Lernt weiter, euer ganzes Leben lang. Bleibt neugierig und helft einander. Nach der Schule nicht mehr zu lernen, das rate ich nicht, im Gegenteil."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich für die Schüler, für ihr Leben?"},{"speaker":"Wagner","gender":"f","text":"Dass sie glücklich werden und einen Beruf finden, der ihnen gefällt. Ich wünsche mir, dass die Schüler glücklich werden, das ist das Wichtigste."}],"items":[{"q":"Frau Wagner sagt, die Schüler müssen heute schon alles wissen.","correct":"nein"},{"q":"Für sie ist dieser Tag ein großer Tag.","correct":"ja"},{"q":"Sie findet, eine Ausbildung ist genauso gut wie ein Studium.","correct":"ja"},{"q":"Sie rät den Schülern, nach der Schule nicht mehr zu lernen.","correct":"nein"},{"q":"Sie wünscht sich, dass die Schüler glücklich werden.","correct":"ja"}]}]};
